#!/usr/bin/env bash
#
# refresh-rule.sh — regenerate the auto-generated dev-stack state in ~/.claude/reference/dev-stack-state.md
#   (moved out of ~/.claude/CLAUDE.md on 2026-11-17 so sessions do not load it; CLAUDE.md keeps a pointer)
#
# Reads the current state of ~/.claude/skills/ and ~/.local/bin/, classifies
# each skill by which dev-stack tier it belongs to (first-party / kb-skill /
# superpowers / vendor/local / external), and replaces the content between
# the auto-gen markers in that file (CLAUDE_MD overrides the path).
#
# Classification is based on the dev-stack repo as source of truth (does the
# tier folder contain a directory with this name?), NOT on symlink resolution,
# so it works even when skills are linked from a legacy ~/.agents/skills/.
#
# Usage:
#   refresh-rule.sh           # apply changes
#   refresh-rule.sh --dry-run # print what would change without writing
#   refresh-rule.sh --check   # exit 1 if drift exists, 0 if clean (for hooks)
#
# Markers in CLAUDE.md must look like:
#   <!-- BEGIN AUTO-GENERATED: dev-stack-state do-not-edit-by-hand -->
#   ...
#   <!-- END AUTO-GENERATED: dev-stack-state -->

set -euo pipefail

CLAUDE_MD="${CLAUDE_MD:-$HOME/.claude/reference/dev-stack-state.md}"
DEV_STACK="${DEV_STACK:-$HOME/code/dev-stack}"
BEGIN_MARKER='<!-- BEGIN AUTO-GENERATED: dev-stack-state do-not-edit-by-hand -->'
END_MARKER='<!-- END AUTO-GENERATED: dev-stack-state -->'

mode="apply"
case "${1:-}" in
  --dry-run) mode="dry-run" ;;
  --check)   mode="check" ;;
  --help|-h)
    sed -n '3,20p' "$0" | sed 's/^# *//'
    exit 0
    ;;
esac

# --- Classify each installed skill by checking the dev-stack repo ---
classify_skill() {
  local name="$1"
  if [ -d "$DEV_STACK/skills/$name" ];                     then echo "first-party";  return; fi
  if [ -d "$DEV_STACK/vendor/kb-skill/skills/$name" ];     then echo "kb-skill";     return; fi
  if [ -d "$DEV_STACK/vendor/superpowers/skills/$name" ];  then echo "superpowers";  return; fi
  if [ -d "$DEV_STACK/vendor/local/skills/$name" ];        then echo "vendor-local"; return; fi
  echo "external"
}

# --- Classify each installed agent by checking the dev-stack repo ---
classify_agent() {
  local name="$1"
  if [ -f "$DEV_STACK/agents/$name.md" ]; then
    echo "dev-stack"
    return
  fi
  echo "external"
}

# --- Read the `model:` frontmatter field from an agent definition ---
agent_model() {
  local file="$1"
  [ -f "$file" ] || { echo "?"; return; }
  awk -F': *' '
    /^---$/ { n++; if (n==2) exit; next }
    n==1 && $1=="model" { print $2; exit }
  ' "$file" | tr -d '[:space:]' | head -c 20
}

# --- Build the new section content ---
build_section() {
  local timestamp
  timestamp=$(date '+%Y-%m-%d %H:%M:%S %z')
  local skill_count
  skill_count=$(ls "$HOME/.claude/skills/" 2>/dev/null | wc -l | tr -d ' ')

  printf '%s\n' "$BEGIN_MARKER"
  printf '\n*Auto-generated by `scripts/refresh-rule.sh`. Do not edit by hand — your changes will be overwritten on the next refresh. Last updated: %s.*\n\n' "$timestamp"
  printf '**Currently installed skills (%s total):**\n\n' "$skill_count"
  printf '| Tier | Skills |\n'
  printf '|---|---|\n'

  for tier in first-party kb-skill superpowers vendor-local external; do
    local skills_in_tier=""
    for skill in $(ls "$HOME/.claude/skills/" 2>/dev/null | sort); do
      [ "$(classify_skill "$skill")" = "$tier" ] || continue
      if [ -z "$skills_in_tier" ]; then
        skills_in_tier="\`$skill\`"
      else
        skills_in_tier="$skills_in_tier, \`$skill\`"
      fi
    done
    if [ -n "$skills_in_tier" ]; then
      printf '| %s | %s |\n' "$tier" "$skills_in_tier"
    fi
  done

  # --- Agents table ---
  local agent_count
  agent_count=0
  if [ -d "$HOME/.claude/agents/" ]; then
    agent_count=$(find "$HOME/.claude/agents/" -maxdepth 1 \( -type f -o -type l \) -name '*.md' | wc -l | tr -d ' ')
  fi
  agent_count=${agent_count:-0}
  if [ "$agent_count" -gt 0 ]; then
    printf '\n**Registered subagents (%s total):**\n\n' "$agent_count"
    printf '| Agent | Source | Default model |\n'
    printf '|---|---|---|\n'
    for f in "$HOME/.claude/agents/"*.md; do
      [ -f "$f" ] || [ -L "$f" ] || continue
      local agent_name tier model
      agent_name=$(basename "$f" .md)
      tier=$(classify_agent "$agent_name")
      model=$(agent_model "$f")
      [ -z "$model" ] && model="?"
      printf '| `%s` | %s | %s |\n' "$agent_name" "$tier" "$model"
    done
  else
    local parked_agent_count
    parked_agent_count=0
    if [ -d "$HOME/.claude/agents-parked/" ]; then
      parked_agent_count=$(find "$HOME/.claude/agents-parked/" -maxdepth 1 \( -type f -o -type l \) -name '*.md' | wc -l | tr -d ' ')
    fi
    if [ "$parked_agent_count" -gt 0 ]; then
      printf '\n**Subagents:** none loaded; %s parked in ~/.claude/agents-parked (use jdelegate --role <name>).\n' "$parked_agent_count"
    fi
  fi

  printf '\n**Helpers in `~/.local/bin/` (from dev-stack):**\n'
  if [ -d "$DEV_STACK/bin" ]; then
    for src in "$DEV_STACK"/bin/*; do
      [ -f "$src" ] || continue
      local name
      name=$(basename "$src")
      if [ -e "$HOME/.local/bin/$name" ]; then
        printf -- '- `%s` ✓\n' "$name"
      else
        printf -- '- `%s` ⚠️  not in PATH (run install.sh)\n' "$name"
      fi
    done
  fi

  printf '\n**Hook source:** `~/.claude/hooks/user-prompt-kb-check.sh`'
  if [ -L "$HOME/.claude/hooks/user-prompt-kb-check.sh" ]; then
    local hook_target
    hook_target=$(readlink "$HOME/.claude/hooks/user-prompt-kb-check.sh")
    case "$hook_target" in
      *"/dev-stack/hooks/"*) printf ' → linked to dev-stack ✓' ;;
      *)                     printf ' → external symlink (may drift)' ;;
    esac
  else
    printf ' → standalone copy (may drift from dev-stack)'
  fi
  printf '\n\n'

  printf '%s\n' "$END_MARKER"
}

# --- Read current state ---
if [ ! -f "$CLAUDE_MD" ]; then
  echo "refresh-rule: $CLAUDE_MD not found" >&2
  exit 1
fi

if ! grep -Fq "$BEGIN_MARKER" "$CLAUDE_MD"; then
  echo "refresh-rule: auto-gen markers not found in $CLAUDE_MD" >&2
  echo "refresh-rule: add these two lines somewhere in CLAUDE.md to bootstrap:" >&2
  echo "  $BEGIN_MARKER" >&2
  echo "  $END_MARKER" >&2
  exit 2
fi

# --- Compute new section into a temp file (avoids awk multi-line -v issues) ---
new_section_file=$(mktemp)
trap 'rm -f "$new_section_file"' EXIT
build_section > "$new_section_file"

# --- Extract the current section into another temp file ---
current_section_file=$(mktemp)
trap 'rm -f "$new_section_file" "$current_section_file"' EXIT
awk -v begin="$BEGIN_MARKER" -v end="$END_MARKER" '
  $0 == begin { capture=1 }
  capture { print }
  $0 == end { capture=0 }
' "$CLAUDE_MD" > "$current_section_file"

# --- Compare (ignore the timestamp line, which changes every run) ---
new_norm=$(mktemp)
cur_norm=$(mktemp)
trap 'rm -f "$new_section_file" "$current_section_file" "$new_norm" "$cur_norm"' EXIT
grep -v 'Last updated:' "$new_section_file" > "$new_norm"
grep -v 'Last updated:' "$current_section_file" > "$cur_norm"

if cmp -s "$new_norm" "$cur_norm"; then
  case "$mode" in
    check)   exit 0 ;;
    dry-run) echo "refresh-rule: no drift, CLAUDE.md is up-to-date" ;;
    apply)   echo "refresh-rule: no drift, nothing to do" ;;
  esac
  exit 0
fi

# --- Drift detected ---
case "$mode" in
  check)
    new_count=$(wc -l < "$new_section_file" | tr -d ' ')
    cur_count=$(wc -l < "$current_section_file" | tr -d ' ')
    echo "DRIFT (current: $cur_count lines, new: $new_count lines)"
    exit 1
    ;;
  dry-run)
    echo "=== refresh-rule: drift detected, here is the diff ==="
    diff -u "$current_section_file" "$new_section_file" || true
    echo
    echo "Run without --dry-run to apply."
    exit 0
    ;;
  apply)
    # Replace the section in CLAUDE.md by reading the new content from a file
    tmp=$(mktemp)
    awk -v begin="$BEGIN_MARKER" -v end="$END_MARKER" -v newfile="$new_section_file" '
      $0 == begin {
        while ((getline line < newfile) > 0) print line
        close(newfile)
        skip = 1
        next
      }
      $0 == end {
        skip = 0
        next
      }
      !skip { print }
    ' "$CLAUDE_MD" > "$tmp"
    mv "$tmp" "$CLAUDE_MD"
    echo "refresh-rule: applied. CLAUDE.md updated."
    ;;
esac
